{"file_path": "src/modules/ai-content/adapters/components/report-mode/DocumentToolbar.tsx", "overwrite": true, "initial_content": "'use client';

import React from 'react';
import { Project } from '@/modules/projects/domain/entities/Project';
import { formatDistanceToNow } from 'date-fns';
import { Button } from '@/components/ui/button';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import { Eye, PenLine, ListTree, Maximize2, Minimize2, Lightbulb, BookOpen, Clock } from 'lucide-react';
import { cn } from '@/infrastructure/utils/cn';

interface DocumentToolbarProps {
    project: Project | null;
    viewMode: 'edit' | 'preview';
    setViewMode: (mode: 'edit' | 'preview') => void;
    isOutlineVisible: boolean;
    setIsOutlineVisible: (visible: boolean) => void;
    isFullscreen: boolean;
    toggleFullscreen: () => void;
    suggestion: string;
    showCoverPage: boolean;
    setShowCoverPage: (visible: boolean) => void;
}

export const DocumentToolbar = ({
    project,
    viewMode,
    setViewMode,
    isOutlineVisible,
    setIsOutlineVisible,
    isFullscreen,
    toggleFullscreen,
    suggestion,
    showCoverPage,
    setShowCoverPage,
}: DocumentToolbarProps) => {
    return (
        <div className="flex items-center justify-between px-4 py-2 border-b border-border/40 bg-background/60 backdrop-blur-xl sticky top-0 z-10">

            {/* Left — status indicators */}
            <div className="flex items-center gap-3">
                {/* Live Preview badge */}
                <div className="flex items-center gap-1.5 text-[9px] text-muted-foreground font-black uppercase tracking-[0.22em] bg-background/70 px-2.5 py-1 rounded-full border border-border/30 shadow-sm">
                    <span className="h-1.5 w-1.5 rounded-full bg-green-500 animate-pulse" />
                    Live
                </div>

                {/* Divider */}
                <div className="w-px h-4 bg-border/40" aria-hidden />

                {/* Auto-save timestamp */}
                {project?.meta.updated ? (
                    <span className="flex items-center gap-1 text-[9px] text-muted-foreground/50 font-bold uppercase tracking-[0.15em]">
                        <Clock className="h-2.5 w-2.5 opacity-50" />
                        {formatDistanceToNow(new Date(project.meta.updated), { addSuffix: true })}
                    </span>
                ) : (
                    <span className="text-[9px] text-muted-foreground/30 font-bold uppercase tracking-[0.15em]">
                        Not saved yet
                    </span>
                )}
            </div>

            {/* Right — action buttons */}
            <div className="flex items-center gap-0.5">
                <TooltipProvider delayDuration={300}>

                    {/* Group 1 — view mode */}
                    <Tooltip>
                        <TooltipTrigger asChild>
                            <Button
                                variant="ghost"
                                size="icon"
                                aria-label={viewMode === 'edit' ? 'Switch to Preview' : 'Switch to Edit'}
                                className={cn(
                                    "h-7 w-7 rounded-lg transition-all duration-200",
                                    viewMode === 'edit'
                                        ? "bg-primary/10 text-primary shadow-sm"
                                        : "hover:bg-primary/5 hover:text-primary text-muted-foreground"
                                )}
                                onClick={() => setViewMode(viewMode === 'edit' ? 'preview' : 'edit')}
                            >
                                {viewMode === 'edit'
                                    ? <Eye className="h-3.5 w-3.5" />
                                    : <PenLine className="h-3.5 w-3.5" />}
                            </Button>
                        </TooltipTrigger>
                        <TooltipContent side="bottom" className="text-[9px] font-black uppercase tracking-[0.2em] bg-background/95 backdrop-blur-md border-primary/20 mt-2">
                            {viewMode === 'edit' ? 'Preview Mode' : 'Edit Mode'}
                            <span className="opacity-50 ml-1.5 font-normal normal-case tracking-normal">
                                {viewMode === 'edit' ? 'Ctrl P' : 'Ctrl E'}
                            </span>
                        </TooltipContent>
                    </Tooltip>

                    {/* Divider */}
                    <div className="w-px h-4 bg-border/40 mx-1.5" aria-hidden />

                    {/* Group 2 — document controls */}
                    <Tooltip>
                        <TooltipTrigger asChild>
                            <Button
                                variant="ghost"
                                size="icon"
                                aria-label={isOutlineVisible ? 'Hide document outline' : 'Show document outline'}
                                className={cn(
                                    "h-7 w-7 rounded-lg transition-all duration-200",
                                    isOutlineVisible
                                        ? "bg-primary/10 text-primary shadow-sm"
                                        : "hover:bg-primary/5 hover:text-primary text-muted-foreground"
                                )}
                                onClick={() => setIsOutlineVisible(!isOutlineVisible)}
                            >
                                <ListTree className="h-3.5 w-3.5" />
                            </Button>
                        </TooltipTrigger>
                        <TooltipContent side="bottom" className="text-[9px] font-black uppercase tracking-[0.2em] bg-background/95 backdrop-blur-md border-primary/20 mt-2">
                            {isOutlineVisible ? 'Hide Outline' : 'Show Outline'}
                        </TooltipContent>
                    </Tooltip>

                    <Tooltip>
                        <TooltipTrigger asChild>
                            <Button
                                variant="ghost"
                                size="icon"
                                aria-label={showCoverPage ? 'Hide cover page' : 'Show cover page'}
                                className={cn(
                                    "h-7 w-7 rounded-lg transition-all duration-200",
                                    showCoverPage
                                        ? "bg-primary/10 text-primary shadow-sm"
                                        : "hover:bg-primary/5 hover:text-primary text-muted-foreground"
                                )}
                                onClick={() => setShowCoverPage(!showCoverPage)}
                            >
                                <BookOpen className="h-3.5 w-3.5" />
                            </Button>
                        </TooltipTrigger>
                        <TooltipContent side="bottom" className="text-[9px] font-black uppercase tracking-[0.2em] bg-background/95 backdrop-blur-md border-primary/20 mt-2">
                            {showCoverPage ? 'Hide Cover Page' : 'Show Cover Page'}
                        </TooltipContent>
                    </Tooltip>

                    {/* Divider */}
                    <div className="w-px h-4 bg-border/40 mx-1.5" aria-hidden />

                    {/* Group 3 — utility */}
                    <Tooltip>
                        <TooltipTrigger asChild>
                            <Button
                                variant="ghost"
                                size="icon"
                                aria-label={isFullscreen ? 'Exit fullscreen' : 'Enter fullscreen'}
                                className="h-7 w-7 rounded-lg hover:bg-primary/5 hover:text-primary text-muted-foreground transition-all duration-200"
                                onClick={toggleFullscreen}
                            >
                                {isFullscreen
                                    ? <Minimize2 className="h-3.5 w-3.5" />
                                    : <Maximize2 className="h-3.5 w-3.5" />}
                            </Button>
                        </TooltipTrigger>
                        <TooltipContent side="bottom" className="text-[9px] font-black uppercase tracking-[0.2em] bg-background/95 backdrop-blur-md border-primary/20 mt-2">
                            {isFullscreen ? 'Exit Fullscreen' : 'Fullscreen'}
                            <span className="opacity-50 ml-1.5 font-normal normal-case tracking-normal">F11</span>
                        </TooltipContent>
                    </Tooltip>

                    <Tooltip>
                        <TooltipTrigger asChild>
                            <Button
                                variant="ghost"
                                size="sm"
                                aria-label="Writer's guide and intelligent suggestions"
                                className="h-7 text-[9px] font-black uppercase tracking-[0.18em] gap-1.5 px-2.5 rounded-lg hover:bg-amber-500/10 hover:text-amber-600 dark:hover:text-amber-400 text-muted-foreground transition-all duration-200"
                            >
                                <Lightbulb className="h-3 w-3 text-amber-500" />
                                Guide
                            </Button>
                        </TooltipTrigger>
                        <TooltipContent
                            side="bottom"
                            className="max-w-[260px] p-4 space-y-2 bg-background/95 backdrop-blur-md border-primary/20 mt-2"
                        >
                            <p className="text-[9px] font-black uppercase tracking-[0.2em] text-primary">
                                Intelligent Suggestion
                            </p>
                            <p className="text-[11px] leading-relaxed text-muted-foreground italic">
                                {suggestion}
                            </p>
                        </TooltipContent>
                    </Tooltip>

                </TooltipProvider>
            </div>
        </div>
    );
};
"}

{"file_path": "src/modules/ai-content/adapters/components/report-mode/layout/SidebarContainer.tsx", "overwrite": true, "initial_content": "'use client';

import React from 'react';
import { ScrollArea } from '@/components/ui/scroll-area';
import { cn } from '@/infrastructure/utils/cn';

interface SidebarContainerProps {
    title: string;
    icon?: React.ReactNode;
    actions?: React.ReactNode;
    children: React.ReactNode;
    className?: string;
}

export const SidebarContainer = ({
    title,
    icon,
    actions,
    children,
    className
}: SidebarContainerProps) => {
    return (
        <div className={cn(
            "flex flex-col h-full bg-background/40 backdrop-blur-2xl relative overflow-hidden",
            className
        )}>
            {/* Dot-grid atmosphere — aligned with BuilderCanvas (28px, 1.5px center) */}
            <div
                className="absolute inset-0 opacity-[0.02] dark:opacity-[0.04] pointer-events-none"
                style={{
                    backgroundImage: 'radial-gradient(circle at 1.5px 1.5px, hsl(var(--primary)) 1px, transparent 0)',
                    backgroundSize: '28px 28px',
                }}
            />

            {/* Sticky Technical Header */}
            <header className="h-11 shrink-0 px-5 flex items-center justify-between border-b border-border/40 bg-background/50 backdrop-blur-2xl relative z-20">
                {/* Subtle left accent line */}
                <div className="absolute left-0 inset-y-2 w-[2px] rounded-full bg-primary/20" aria-hidden />

                <div className="flex items-center gap-2 min-w-0">
                    {icon && (
                        <span className="text-primary/50 shrink-0">
                            {icon}
                        </span>
                    )}
                    <h2 className="text-[10px] font-black uppercase tracking-[0.22em] text-foreground/70 truncate">
                        {title}
                    </h2>
                </div>

                {actions && (
                    <div className="flex items-center gap-1 shrink-0 ml-2">
                        {actions}
                    </div>
                )}
            </header>

            {/* Scrollable Content Area */}
            <ScrollArea className="flex-1 min-h-0 relative z-10">
                <div className="p-5 flex flex-col gap-6 pb-20">
                    {children}
                </div>
            </ScrollArea>

            {/* Bottom fade — matches canvas gradient style */}
            <div className="absolute inset-x-0 bottom-0 h-14 bg-gradient-to-t from-background/60 to-transparent pointer-events-none z-20" />
        </div>
    );
};
"}

