  40       // Find nearest heading node above cursor position
  41       const { $anchor } = editor.state.selection;
  42       let headingText: string | null = null;
  43       for (let depth = $anchor.depth; depth >= 0; depth--) {
  44         const node = $anchor.node(depth);
  45         if (node.type.name === 'heading') {
  46           headingText = node.textContent;
  47           break;
  48         }
  49       }
  50       // Walk backwards through doc to find nearest heading before cursor
  51       if (!headingText) {
  52         const pos = $anchor.pos;
  53         editor.state.doc.nodesBetween(0, pos, (node) => {
  54           if (node.type.name === 'heading') {
